   44	/** Uma forma de entrega: cada nova opção é uma nova implementação registrada em {@link ShippingMethods}. */
   45	interface ShippingMethod {
   46	    String code();
   47	
   48	    /** Verdadeiro se a opção tem frete (a retirada na loja não tem). */
   49	    boolean chargesShipping();
   50	
   51	    /** Verdadeiro se o frete pode ser isentado por vantagem do clube (falso para serviço terceirizado). */
   52	    boolean waivableByClub();
   53	
   54	    /** @throws ApiException SHIPPING_METHOD_UNAVAILABLE (422) ou CARRIER_UNAVAILABLE (503) */
   55	    ShippingQuote quote(ShippingContext ctx);
   56	}
