   60	class CarrierDownException extends RuntimeException {
   61	    CarrierDownException(String message, Throwable cause) {
   62	        super(message, cause);
   63	    }
   64	}
   65	
   66	/** Transportadora externa. Optional vazio = CEP não atendido. */
   67	interface CarrierGateway {
   68	    Optional<CarrierQuote> quote(String zipCode, long weightGrams, String service) throws CarrierDownException;
   69	}
