   71	class CarrierShippingMethod implements ShippingMethod {
   72	    private final String code;
   73	    private final String service;
   74	    private final CarrierGateway gateway;
   75	
   76	    CarrierShippingMethod(String code, String service, CarrierGateway gateway) {
   77	        this.code = code;
   78	        this.service = service;
   79	        this.gateway = gateway;
   80	    }
   81	
   82	    public String code() { return code; }
   83	
   84	    public boolean chargesShipping() { return true; }
   85	
   86	    public boolean waivableByClub() { return true; }
   87	
   88	    public ShippingQuote quote(ShippingContext ctx) {
   89	        Optional<CarrierQuote> quote;
   90	        try {
   91	            quote = gateway.quote(ctx.zipCode(), ctx.weightGrams(), service);
   92	        } catch (CarrierDownException e) {
   93	            throw new ApiException("CARRIER_UNAVAILABLE", 503);
   94	        }
   95	        CarrierQuote q = quote.orElseThrow(() -> ApiException.unprocessable("SHIPPING_METHOD_UNAVAILABLE"));
   96	        int days = (q.etaHours() + 23) / 24 + ctx.region().carrierExtraDays();
   97	        return new ShippingQuote(Money.round(q.price()), days);
   98	    }
   99	}
