  178	final class Coupons {
  179	    /** Nenhum cupom pode passar de 30% do valor dos produtos. */
  180	    private static final String MAX_DISCOUNT_RATE = "0.30";
  181	
  182	    private final Map<String, Coupon> byCode = new LinkedHashMap<>();
  183	
  184	    Coupons(Coupon... coupons) {
  185	        for (Coupon c : coupons) byCode.put(c.code(), c);
  186	    }
  187	
  188	    static Coupons standard() {
  189	        return new Coupons(new Welcome10(), new Minus50(), new FreeShipping(), new Buy3Pay2());
  190	    }
  191	
  192	    Coupon get(String code) {
  193	        return code == null ? null : byCode.get(code);
  194	    }
  195	
  196	    BigDecimal discountFor(Coupon coupon, CouponContext ctx) {
  197	        BigDecimal discount = Money.round(coupon.discount(ctx));
  198	        BigDecimal cap = Money.percent(ctx.productsSubtotal(), MAX_DISCOUNT_RATE);
  199	        return discount.compareTo(cap) > 0 ? cap : discount;
  200	    }
  201	
  202	    static final class Welcome10 implements Coupon {
  203	        public String code() { return "WELCOME10"; }
  204	
  205	        public BigDecimal discount(CouponContext ctx) {
  206	            if (!ctx.firstPurchase().getAsBoolean()) throw Coupon.notApplicable();
  207	            return Money.percent(ctx.productsSubtotal(), "0.10");
  208	        }
  209	    }
  210	
  211	    static final class Minus50 implements Coupon {
  212	        public String code() { return "MINUS50"; }
  213	
  214	        public BigDecimal discount(CouponContext ctx) {
  215	            if (ctx.productsSubtotal().compareTo(new BigDecimal("300.00")) < 0) throw Coupon.notApplicable();
  216	            return new BigDecimal("50.00");
  217	        }
  218	    }
  219	
  220	    static final class FreeShipping implements Coupon {
  221	        public String code() { return "FREESHIPPING"; }
  222	
  223	        public BigDecimal discount(CouponContext ctx) {
  224	            if (!ctx.shippingMethod().chargesShipping()) throw Coupon.notApplicable();
  225	            return ctx.shippingCost();
  226	        }
  227	    }
  228	
  229	    static final class Buy3Pay2 implements Coupon {
  230	        public String code() { return "BUY3PAY2"; }
  231	
  232	        public BigDecimal discount(CouponContext ctx) {
  233	            BigDecimal total = BigDecimal.ZERO;
  234	            for (CartLine line : ctx.lines()) {
  235	                total = total.add(line.product().price().multiply(BigDecimal.valueOf(line.quantity() / 3)));
  236	            }
  237	            return total;
  238	        }
  239	    }
