148	/** Uma forma de pagamento: cada nova forma é uma nova implementação registrada em {@link PaymentMethods}. */
149	interface PaymentMethod {
150	    String code();
151	
152	    boolean acceptsInstallments(int installments);
153	
154	    boolean availableFor(BigDecimal orderTotal);
155	
156	    PaymentOutcome settle(BigDecimal orderTotal, int installments, boolean couponUsed);
157	}
