159	final class PaymentMethods {
160	    private final Map<String, PaymentMethod> byCode = new LinkedHashMap<>();
161	
162	    PaymentMethods(PaymentMethod... methods) {
163	        for (PaymentMethod m : methods) byCode.put(m.code(), m);
164	    }
165	
166	    static PaymentMethods standard() {
167	        return new PaymentMethods(new Pix(), new CreditCard(), new BankSlip());
168	    }
169	
170	    PaymentMethod get(String code) {
171	        return code == null ? null : byCode.get(code);
172	    }
173	
174	    static final class Pix implements PaymentMethod {
175	        public String code() { return "PIX"; }
176	
177	        public boolean acceptsInstallments(int n) { return n == 1; }
178	
179	        public boolean availableFor(BigDecimal total) { return true; }
180	
181	        public PaymentOutcome settle(BigDecimal total, int n, boolean couponUsed) {
182	            BigDecimal result = couponUsed ? total : total.subtract(Money.percent(total, "0.05"));
183	            return new PaymentOutcome(result, result);
184	        }
185	    }
186	
187	    static final class BankSlip implements PaymentMethod {
188	        private static final BigDecimal FEE = new BigDecimal("3.49");
189	        private static final BigDecimal MAX_TOTAL = new BigDecimal("1000.00");
190	
191	        public String code() { return "BANK_SLIP"; }
192	
193	        public boolean acceptsInstallments(int n) { return n == 1; }
194	
195	        public boolean availableFor(BigDecimal total) { return total.compareTo(MAX_TOTAL) <= 0; }
196	
197	        public PaymentOutcome settle(BigDecimal total, int n, boolean couponUsed) {
198	            BigDecimal result = total.add(FEE);
199	            return new PaymentOutcome(result, result);
200	        }
201	    }
202	
203	    static final class CreditCard implements PaymentMethod {
204	        private static final int MAX_INTEREST_FREE = 3;
205	        private static final BigDecimal MONTHLY_RATE = new BigDecimal("0.0199");
206	        private static final MathContext MC = new MathContext(40);
207	
208	        public String code() { return "CREDIT_CARD"; }
209	
210	        public boolean acceptsInstallments(int n) { return n >= 1 && n <= 12; }
211	
212	        public boolean availableFor(BigDecimal total) { return true; }
213	
214	        public PaymentOutcome settle(BigDecimal total, int n, boolean couponUsed) {
215	            BigDecimal count = BigDecimal.valueOf(n);
216	            if (n <= MAX_INTEREST_FREE) {
217	                return new PaymentOutcome(total, total.divide(count, 2, RoundingMode.HALF_EVEN));
218	            }
219	            // Tabela Price: parcela = total * i / (1 - (1 + i)^-n)
220	            BigDecimal growth = BigDecimal.ONE.add(MONTHLY_RATE).pow(n, MC);
221	            BigDecimal denominator = BigDecimal.ONE.subtract(BigDecimal.ONE.divide(growth, MC), MC);
222	            BigDecimal installment = Money.round(total.multiply(MONTHLY_RATE).divide(denominator, MC));
223	            return new PaymentOutcome(installment.multiply(count), installment);
224	        }
225	    }
