308	package shop;
309	
310	import java.math.BigDecimal;
311	import java.util.ArrayList;
312	import java.util.HashMap;
313	import java.util.HashSet;
314	import java.util.List;
315	import java.util.Map;
316	import java.util.Set;
317	import java.util.regex.Pattern;
318	
319	/** Único lugar onde o resumo é calculado: o resumo e o registro do pedido passam por aqui. */
320	class PricingService {
321	    private static final Pattern ZIP = Pattern.compile("\\d{8}");
322	
323	    private final ShippingMethods shipping;
324	    private final Coupons coupons;
325	    private final PaymentMethods payments;
326	
327	    PricingService(ShippingMethods shipping, Coupons coupons, PaymentMethods payments) {
328	        this.shipping = shipping;
329	        this.coupons = coupons;
330	        this.payments = payments;
331	    }
332	
333	    Summary calculate(CheckoutRequest r, Tx tx) {
334	        List<CartLine> lines = loadCart(r, tx);
335	
336	        ClubTier tier = ClubTier.parse(r.clubTier());
337	        if (tier == null) throw ApiException.unprocessable("INVALID_CLUB_TIER");
338	        Region region = Region.parse(r.region());
339	        if (region == null) throw ApiException.unprocessable("INVALID_REGION");
340	        if (r.zipCode() == null || !ZIP.matcher(r.zipCode()).matches()) {
341	            throw ApiException.unprocessable("INVALID_ZIP_CODE");
342	        }
343	        ShippingMethod method = shipping.get(r.shippingMethod());
344	        if (method == null) throw ApiException.unprocessable("INVALID_SHIPPING_METHOD");
345	
346	        BigDecimal subtotal = BigDecimal.ZERO;
347	        BigDecimal weight = BigDecimal.ZERO;
348	        for (CartLine l : lines) {
349	            subtotal = subtotal.add(l.total());
350	            weight = weight.add(l.product().weightKg().multiply(BigDecimal.valueOf(l.quantity())));
351	        }
352	        subtotal = Money.round(subtotal);
353	
354	        ShippingQuote quote = method.quote(new ShippingContext(r.zipCode(), weight, region));
355	        BigDecimal shippingCost = tier.waivesShipping() && method.waivableByClub() ? Money.ZERO : quote.cost();
356	
357	        BigDecimal couponDiscount = Money.ZERO;
358	        if (r.couponPresent()) {
359	            Coupon coupon = coupons.get(r.coupon());
360	            if (coupon == null) throw ApiException.unprocessable("INVALID_COUPON");
361	            CouponContext ctx = new CouponContext(lines, subtotal, shippingCost, method,
362	                    () -> !tx.hasFulfilledOrder(r.cpf()));
363	            couponDiscount = coupons.discountFor(coupon, ctx);
364	        }
365	
366	        BigDecimal insurance = region.insurance(subtotal);
367	        BigDecimal orderTotal = Money.round(subtotal.subtract(couponDiscount).add(shippingCost).add(insurance));
368	
369	        PaymentMethod payment = payments.get(r.paymentMethod());
370	        if (payment == null) throw ApiException.unprocessable("INVALID_PAYMENT_METHOD");
371	        if (!payment.acceptsInstallments(r.installments())) throw ApiException.unprocessable("INVALID_INSTALLMENTS");
372	        if (!payment.availableFor(orderTotal)) throw ApiException.unprocessable("PAYMENT_METHOD_UNAVAILABLE");
373	        PaymentOutcome outcome = payment.settle(orderTotal, r.installments(), r.couponPresent());
374	        BigDecimal finalTotal = Money.round(outcome.finalTotal());
375	
376	        return new Summary(subtotal, couponDiscount, shippingCost, quote.days(), insurance,
377	                finalTotal.subtract(orderTotal), finalTotal, r.installments(), outcome.installmentAmount(),
378	                tier.credit(subtotal), tier.gift(subtotal));
379	    }
380	
381	    private List<CartLine> loadCart(CheckoutRequest r, Tx tx) {
382	        if (r.cpf() == null || r.cpf().isBlank() || r.email() == null || r.email().isBlank()
383	                || r.items().isEmpty()) {
384	            throw ApiException.unprocessable("INVALID_ORDER");
385	        }
386	        Set<String> seen = new HashSet<>();
387	        for (CheckoutRequest.RawItem i : r.items()) {
388	            if (i.sku() == null || i.sku().isBlank() || i.quantity() == null || i.quantity() <= 0
389	                    || !seen.add(i.sku())) {
390	                throw ApiException.unprocessable("INVALID_ORDER");
391	            }
392	        }
393	        Map<String, Product> products = new HashMap<>();
394	        for (CheckoutRequest.RawItem i : r.items()) {
395	            Product p = tx.findProduct(i.sku()).orElseThrow(() -> ApiException.unprocessable("UNKNOWN_PRODUCT"));
396	            products.put(i.sku(), p);
397	        }
398	        for (Product p : products.values()) {
399	            if (p.discontinued()) throw ApiException.unprocessable("PRODUCT_DISCONTINUED");
400	        }
401	        List<CartLine> lines = new ArrayList<>();
402	        for (CheckoutRequest.RawItem i : r.items()) {
403	            Product p = products.get(i.sku());
404	            if (p.stock() < i.quantity()) throw ApiException.unprocessable("INSUFFICIENT_STOCK");
405	            lines.add(new CartLine(p, i.quantity()));
406	        }
407	        return lines;
408	    }
409	}

