265	import com.fasterxml.jackson.databind.JsonNode;
266	
267	import java.util.ArrayList;
268	import java.util.List;
269	
270	/** Dados da compra, lidos do JSON sem rejeitar nada: a conferência (e a ordem dos erros) fica no cálculo. */
271	record CheckoutRequest(String cpf, String email, List<RawItem> items, String zipCode, String region,
272	                       String shippingMethod, boolean couponPresent, String coupon, String paymentMethod,
273	                       int installments, String clubTier) {
274	
275	    /** sku ou quantity nulos indicam valor ausente ou inválido. */
276	    record RawItem(String sku, Integer quantity) {}
277	
278	    static final int INVALID_INSTALLMENTS = -1;
279	
280	    static CheckoutRequest parse(JsonNode root) {
281	        JsonNode body = root != null && root.isObject() ? root : Json.MAPPER.createObjectNode();
282	        JsonNode customer = body.path("customer");
283	        List<RawItem> items = new ArrayList<>();
284	        JsonNode itemsNode = body.path("items");
285	        if (itemsNode.isArray()) {
286	            for (JsonNode n : itemsNode) {
287	                String sku = n.isObject() ? text(n.get("sku")) : null;
288	                JsonNode q = n.isObject() ? n.get("quantity") : null;
289	                Integer quantity = q != null && q.isIntegralNumber() && q.canConvertToInt() ? q.asInt() : null;
290	                items.add(new RawItem(sku, quantity));
291	            }
292	        }
293	        JsonNode couponNode = body.get("coupon");
294	        boolean couponPresent = couponNode != null && !couponNode.isNull();
295	        JsonNode inst = body.get("installments");
296	        int installments;
297	        if (inst == null || inst.isNull()) installments = 1;
298	        else if (inst.isIntegralNumber() && inst.canConvertToInt()) installments = inst.asInt();
299	        else installments = INVALID_INSTALLMENTS;
300	        return new CheckoutRequest(
301	                customer.isObject() ? text(customer.get("cpf")) : null,
302	                customer.isObject() ? text(customer.get("email")) : null,
303	                items, text(body.get("zipCode")), text(body.get("region")), text(body.get("shippingMethod")),
304	                couponPresent, couponPresent ? couponNode.asText(couponNode.toString()) : null,
305	                text(body.get("paymentMethod")), installments, text(body.get("clubTier")));
306	    }
307	
308	    /** Texto do campo; valores que não são texto viram um texto que nunca é um código válido. */
309	    private static String text(JsonNode n) {
310	        if (n == null || n.isNull()) return null;
311	        return n.isTextual() ? n.asText() : n.toString();
312	    }
313	}
314	package shop;
315	
316	import com.fasterxml.jackson.databind.JsonNode;
317	import com.fasterxml.jackson.databind.ObjectMapper;
318	
319	import java.math.BigDecimal;
320	import java.net.URI;
321	import java.net.http.HttpClient;
322	import java.net.http.HttpRequest;
323	import java.net.http.HttpResponse;
324	import java.time.Duration;
325	import java.util.Optional;
326	import java.util.concurrent.CompletableFuture;
327	import java.util.concurrent.TimeUnit;
328	
329	class TransLogGateway implements CarrierGateway {
330	    private static final ObjectMapper MAPPER = new ObjectMapper();
331	    private static final long TIMEOUT_MS = 2000;
332	
333	    private final String baseUrl;
334	    private final HttpClient client = HttpClient.newBuilder().connectTimeout(Duration.ofMillis(TIMEOUT_MS)).build();
335	
336	    TransLogGateway(String baseUrl) {
337	        this.baseUrl = baseUrl == null ? null : baseUrl.replaceAll("/+$", "");
338	    }
339	
340	    @Override
341	    public Optional<CarrierQuote> quote(String zipCode, long weightGrams, String service) {
342	        if (baseUrl == null || baseUrl.isBlank()) throw new CarrierDownException("TRANSLOG_URL not set", null);
343	        CompletableFuture<HttpResponse<String>> future = null;
344	        try {
345	            URI uri = URI.create(baseUrl + "/v2/quote?zip=" + zipCode + "&weight_g=" + weightGrams + "&service=" + service);
346	            HttpRequest request = HttpRequest.newBuilder(uri).GET().build();
347	            future = client.sendAsync(request, HttpResponse.BodyHandlers.ofString());
348	            HttpResponse<String> response = future.get(TIMEOUT_MS, TimeUnit.MILLISECONDS);
349	            if (response.statusCode() != 200) throw new CarrierDownException("status " + response.statusCode(), null);
350	            return parse(response.body());
351	        } catch (CarrierDownException e) {
352	            throw e;
353	        } catch (InterruptedException e) {
354	            Thread.currentThread().interrupt();
355	            throw new CarrierDownException("interrupted", e);
356	        } catch (Exception e) {
357	            throw new CarrierDownException("TransLog failure", e);
358	        } finally {
359	            if (future != null) future.cancel(true);
360	        }
361	    }
362	
363	    private static Optional<CarrierQuote> parse(String body) throws Exception {
364	        JsonNode json = MAPPER.readTree(body);
365	        if (json == null || !json.isObject()) throw new CarrierDownException("unexpected body", null);
366	        JsonNode error = json.get("error");
367	        if (error != null) {
368	            if (error.isTextual() && error.asText().equals("ZIP_NOT_SERVED")) return Optional.empty();
369	            throw new CarrierDownException("carrier error", null);
370	        }
371	        JsonNode price = json.get("price_cents");
372	        JsonNode eta = json.get("eta_hours");
373	        if (price == null || eta == null || !price.isIntegralNumber() || !eta.isIntegralNumber()
374	                || !price.canConvertToLong() || !eta.canConvertToInt() || price.asLong() < 0 || eta.asInt() < 0) {
375	            throw new CarrierDownException("unexpected body", null);
376	        }
377	        return Optional.of(new CarrierQuote(BigDecimal.valueOf(price.asLong(), 2), eta.asInt()));
378	    }
379	}
