486	public final class Money {
487	    public static final BigDecimal ZERO = round(BigDecimal.ZERO);
488	
489	    private Money() {}
490	
491	    public static BigDecimal round(BigDecimal value) {
492	        return value.setScale(2, RoundingMode.HALF_EVEN);
493	    }
494	
495	    public static BigDecimal percent(BigDecimal base, String rate) {
496	        return round(base.multiply(new BigDecimal(rate)));
