505	import com.fasterxml.jackson.core.JsonGenerator;
506	
507	final class Json {
508	    static final ObjectMapper MAPPER = new ObjectMapper()
509	            .enable(JsonGenerator.Feature.WRITE_BIGDECIMAL_AS_PLAIN)
510	            .disable(DeserializationFeature.FAIL_ON_UNKNOWN_PROPERTIES)
511	            .disable(SerializationFeature.FAIL_ON_EMPTY_BEANS);
512	
513	    private Json() {}
514	
515	    static String write(Object value) {
516	        try {
517	            return MAPPER.writeValueAsString(value);
518	        } catch (Exception e) {
519	            throw new IllegalStateException(e);
520	        }
521	    }
522	
523	    static <T> T read(String text, Class<T> type) {
524	        try {
525	            return MAPPER.readValue(text, type);
526	        } catch (Exception e) {
527	            throw new IllegalStateException(e);
528	        }
529	    }
530	
531	    /** Lê o corpo; devolve null se for vazio ou não for JSON. */
532	    static JsonNode tree(String text) {
533	        try {
534	            return text == null || text.isBlank() ? null : MAPPER.readTree(text);
535	        } catch (Exception e) {
536	            return null;
537	        }
538	    }
539	}

